export const WARNING = 'GOVERNMENT WARNING: (1) According to the Surgeon General, women should not drink alcoholic beverages during pregnancy because of the risk of birth defects. (2) Consumption of alcoholic beverages impairs your ability to drive a car or operate machinery, and may cause health problems.';
export const FIELDS = {brand:'Brand name',type:'Class / type',abv:'Alcohol (% ABV)',volume:'Net contents',producer:'Producer / bottler and address',origin:'Country of origin'};
export const normalize = s => String(s ?? '').normalize('NFKC').replace(/[’‘]/g,"'").replace(/\s+/g,' ').trim().toLowerCase();
const ws = s => s.replace(/\s+/g,' ').trim();
function contains(text,expected) {const t=normalize(text),e=normalize(expected);return (' '+t+' ').includes(' '+e+' ') || new RegExp('(^|[^a-z0-9])'+e.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'($|[^a-z0-9])').test(t);}
export function volumeMl(s) { const m=String(s).match(/^\s*(\d+(?:\.\d+)?)\s*(ml|cl|l|liters?|litres?|fl\.?\s*oz\.?)\s*$/i);if(!m)return null;return +m[1]*(/^ml$/i.test(m[2])?1:/^cl$/i.test(m[2])?10:/^fl/i.test(m[2])?29.5735295625:1000); }
export function evaluate(text,expected={},confidence=100) {
 const rows=[];const add=(field,status,observed,note)=>rows.push({field,status,expected:expected[field]||'',observed,note});
 for(const field of ['brand','type','producer','origin']) {if(field==='origin'&&!expected.imported){add(field,'skip','—','Not requested for a domestic application.');continue;}const e=expected[field];if(!e){add(field,'review','—','Enter the application value to compare.');continue;}const line=text.split('\n').find(l=>contains(l,e));add(field,contains(text,e)?'match':'review',line||'Not confidently found',contains(text,e)?'Case, apostrophe style and whitespace normalized.':'Check the artwork; text may be absent or misread.');}
 const abvs=[...text.matchAll(/(\d+(?:\.\d+)?)\s*%\s*(?:alc(?:ohol)?\.?\s*(?:\/|by)\s*vol(?:ume)?\.?|abv)/gi),...text.matchAll(/(?:abv|alc(?:ohol)?\.?\s*(?:\/|by)\s*vol(?:ume)?\.?)\s*[:=]?\s*(\d+(?:\.\d+)?)\s*%/gi)].map(m=>Number(m[1]));
 const eabv=Number(expected.abv);add('abv',!expected.abv?'review':abvs.length?(abvs.every(n=>n===eabv)?'match':'mismatch'):'review',abvs.length?[...new Set(abvs)].join(', ')+'%':'Not found',!expected.abv?'Enter application ABV.':abvs.length?'Numeric ABV comparison; proof is not substituted for ABV.':'ABV needs a percent and alcohol qualifier.');
 const vols=[...text.matchAll(/\b\d+(?:\.\d+)?\s*(?:mL|cL|L|liters?|litres?|fl\.?\s*oz\.?)\b/gi)].map(m=>m[0]);const ev=volumeMl(expected.volume);add('volume',ev===null?'review':vols.length?(vols.some(v=>Math.abs(volumeMl(v)-ev)<0.01)?'match':'mismatch'):'review',vols.join(', ')||'Not found',ev===null?'Use a value such as 750 mL or 0.75 L.':'Metric equivalents normalized; check multi-pack and rounded US units manually.');
 const start=text.search(/government\s+warning\s*:/i);const warn=start>=0?ws(text.slice(start)):'';const complete=warn.toLowerCase().startsWith(WARNING.toLowerCase());const caps=warn.startsWith('GOVERNMENT WARNING:');rows.push({field:'warning',expected:WARNING,observed:warn||'Not found',status:complete&&caps?'match':'review',note:complete&&caps?'Wording and punctuation match; heading is uppercase.':'Verify missing/changed words, punctuation or heading capitalization against artwork.'});
 rows.push({field:'format',expected:'Bold uppercase heading; regular-weight body; legible, separate continuous paragraph; correct physical type size.',observed:'Human review required',status:'review',note:'OCR cannot certify bold type, physical millimeters, contrast or placement.'});
 if(confidence<85) for(const row of rows) if(row.status==='match'){row.status='review';row.note+=' Low OCR confidence: confirm on artwork.';}
 return {rows,confidence,status:rows.some(r=>r.status==='mismatch')?'Mismatch found':'Review required',matches:rows.filter(r=>r.status==='match').length};
}
export function parseManifest(raw) {const a=JSON.parse(raw);if(!Array.isArray(a)||a.length>300)throw Error('Use a JSON array with up to 300 applications.');const seen=new Set();for(const x of a){if(!x||typeof x!=='object'||typeof x.filename!=='string'||!x.filename.trim()||seen.has(x.filename))throw Error('Each application needs a unique filename.');seen.add(x.filename);for(const key of Object.keys(FIELDS))if(x[key]!=null&&typeof x[key]!=='string')throw Error(key+' must be text.');if(x.imported!=null&&typeof x.imported!=='boolean')throw Error('imported must be true or false.');if(x.abv&&(!Number.isFinite(+x.abv)||+x.abv<0||+x.abv>100))throw Error('ABV must be from 0 to 100.');}return a;}
